def ts(m=0,s=0): return (base+timedelta(minutes=m,seconds=s)).strftime('%Y-%m-%dT%H:%M:%SZ')
def noise_time(): return (base+timedelta(seconds=rng.randint(-172800,172800))).strftime('%Y-%m-%dT%H:%M:%SZ')
def write(name,special,noise):
 rows=[noise(i) for i in range(N-len(special))]+special; rows.sort(key=lambda x:x.get('_time','')); fields=list(rows[0]);
 for p in (D/name,L/name):
  with p.open('w',newline='',encoding='utf-8') as f: w=csv.DictWriter(f,fieldnames=fields); w.writeheader(); w.writerows(rows)
def wt(p,s): p.parent.mkdir(parents=True,exist_ok=True); p.write_text(textwrap.dedent(s).strip()+'\n',encoding='utf-8')
